insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222001', '11111111-1111-1111-1111-111111110001', 'בית משפט לענייני משפחה ובית דין רבני', 'בישראל אין ערכאה אחת לכל סכסוך משפחתי. נישואין וגירושין של יהודים נתונים לסמכות ייחודית של בתי הדין הרבניים. עניינים כמו מזונות ילדים, החזקת קטינים וחלוקת רכוש נדונים בדרך כלל בבית המשפט לענייני משפחה, אלא אם נכרכו כדין לתביעת הגירושין בבית הדין.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222002', '11111111-1111-1111-1111-111111110002', 'איזון משאבים לפי חוק יחסי ממון', 'חוק יחסי ממון בין בני זוג, התשל״ג-1973, אינו יוצר בעלות משותפת בנכסים במהלך הנישואין. כל אחד מבני הזוג נשאר בעלים של נכסיו, ובמועד פקיעת הנישואין נערך איזון של שווי המשאבים שנצברו בתקופת הנישואין.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222003', '11111111-1111-1111-1111-111111110003', 'מזונות ילדים אחרי בע״מ 919/15', 'חובת מזונות ילדים נשענת על הדין האישי ועל הפסיקה האזרחית. בבע״מ 919/15 קבע בית המשפט העליון כי כאשר זמני השהות משמעותיים אצל שני ההורים, יש לחלק את נטל המזונות לפי יחס ההכנסות וזמני השהות, ולא להטיל אוטומטית את מלוא הנטל על האב.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222004', '11111111-1111-1111-1111-111111110004', 'טובת הילד, החזקה וזמני שהות', 'חוק הכשרות המשפטית והאפוטרופסות קובע ששני ההורים הם האפוטרופסים הטבעיים של ילדם. כשיש מחלוקת, בית המשפט מחליט לפי טובת הילד: קשר עם שני ההורים, יציבות, צרכים רגשיים וחינוכיים, וסיכון אם קיים.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222005', '11111111-1111-1111-1111-111111110022', 'הסכמי ממון: מתי הם תופסים', 'הסכם ממון יכול לשנות את ברירת המחדל של איזון המשאבים, אבל תוקפו תלוי באישור כדין. לפני הנישואין אפשר לאשר אצל נוטריון; אחרי הנישואין נדרש בדרך כלל אישור בית משפט או בית דין.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222006', '11111111-1111-1111-1111-111111110019', 'ידועים בציבור: מעמד וסמכות', 'ידועים בציבור אינם נשואים, ולכן בית הדין הרבני אינו מוסמך בענייני המעמד האישי שלהם כזוג נשוי. המחלוקות ביניהם נדונות בדרך כלל בבית המשפט לענייני משפחה, לפי הלכות שיתוף וחקיקה רלוונטית.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222007', '11111111-1111-1111-1111-111111110014', 'מרוץ הסמכויות: למה מגישים ראשונים', 'מרוץ הסמכויות הוא תופעה ישראלית: מי שמקדים להגיש בערכאה שנוחה לו עשוי לקבוע היכן יידונו עניינים כרוכים. אם תביעת גירושין נפתחת בבית הדין הרבני וכורכים אליה רכוש או ילדים כדין, בית המשפט לענייני משפחה עלול לאבד סמכות באותם עניינים.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222008', '11111111-1111-1111-1111-111111110017', 'סרבנות גט: סנקציות בלי כפיית רצון פסול', 'גט צריך להינתן מרצון. סרבנות גט משאירה את הצד השני עגון או עגונה. החוק מאפשר לבית הדין הרבני להטיל סנקציות על מי שמסרב לקיים פסק דין לגירושין: הגבלת דרכון, רישיון נהיגה, חשבון בנק, ואף מאסר.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222009', '11111111-1111-1111-1111-111111110025', 'מזונות אישה במהלך הנישואין ואחרי הגט', 'מזונות אישה ומזונות ילדים הם חובות שונות. בדין האישי היהודי חייב הבעל במזונות אשתו כל עוד הנישואין קיימים, כל עוד לא הורתה סיבה לשלול אותם. אחרי גט, ככלל אין מזונות אישה מתמשכים כמו במערכות משפט אחרות.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222010', '11111111-1111-1111-1111-111111110034', 'צו הגנה לפי החוק למניעת אלימות במשפחה', 'החוק למניעת אלימות במשפחה, התשנ״א-1991, מאפשר לתת צו הגנה נגד בן משפחה שהתנהג באלימות, שאיים, או שיוצר חשש ממשי לפגיעה. אפשר לבקש צו גם במעמד צד אחד כשיש דחיפות.
insert into public.lessons (id, topic_id, title, intro, estimated_minutes, sources, status, sort_order) values ('22222222-2222-2222-2222-222222222011', '11111111-1111-1111-1111-111111110037', 'ירושה על פי דין לפי חוק הירושה', 'כשאין צוואה תקפה, חוק הירושה, התשכ״ה-1965, קובע מי יורש. בן זוג מקבל את המיטלטלין של משק הבית המשותף ואת המכונית, ואז חלק מהיתרה לפי מי שנשאר: ילדים, הורים, או הוא לבדו.
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333001', '22222222-2222-2222-2222-222222222001', 'זוג יהודים נשוי כדת משה וישראל מבקש להתגרש. איזו ערכאה מוסמכת באופן ייחודי לתת גט?', '[{"id":"a","text":"בית המשפט לענייני משפחה בלבד"},{"id":"b","text":"בית הדין הרבני"},{"id":"c","text":"בית משפט השלום"},{"id":"d","text":"כל ערכאה אזרחית שהצדדים בחרו בהסכם"}]'::jsonb, 'b', 'לפי חוק שיפוט בתי דין רבניים, נישואין וגירושין של יהודים בישראל נתונים לסמכותו הייחודית של בית הדין הרבני. בית המשפט לענייני משפחה אינו נותן גט.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333002', '22222222-2222-2222-2222-222222222001', 'מהו תנאי בסיסי לכריכת עניין רכושי לתביעת גירושין בבית הדין הרבני?', '[{"id":"a","text":"די בכך שאחד הצדדים הזכיר רכוש במכתב"},{"id":"b","text":"הכריכה צריכה להיות כנה, כדין, ובאותו הליך עם תביעת הגירושין"},{"id":"c","text":"די בהסכמת עורך הדין של התובע"},{"id":"d","text":"אין צורך בכריכה; הסמכות תמיד מקבילה"}]'::jsonb, 'b', 'כריכה אינה אוטומטית. הפסיקה דורשת כריכה כנה ועל פי דין: העניין נכרך לתביעת הגירושין עצמה, ולא כניסיון מלאכותי לשלול סמכות מבית המשפט לענייני משפחה.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333003', '22222222-2222-2222-2222-222222222001', 'אם אין כריכה כדין, היכן יידון בדרך כלל סכסוך על החזקת קטינים בין בני זוג יהודים?', '[{"id":"a","text":"רק בבית הדין הרבני"},{"id":"b","text":"רק בבית הדין לעבודה"},{"id":"c","text":"בבית המשפט לענייני משפחה"},{"id":"d","text":"רק בבוררות פרטית"}]'::jsonb, 'c', 'החזקת קטינים וענייני משפחה אחרים שאינם עצם הגירושין נדונים בבית המשפט לענייני משפחה, כל עוד לא נכרכו כדין לבית הדין.', 3) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333004', '22222222-2222-2222-2222-222222222002', 'מהו המועד העקרוני לאיזון משאבים לפי חוק יחסי ממון?', '[{"id":"a","text":"ביום הנישואין"},{"id":"b","text":"בכל שנת מס"},{"id":"c","text":"במועד פקיעת הנישואין"},{"id":"d","text":"רק אחרי מות שני בני הזוג"}]'::jsonb, 'c', 'החוק קובע הסדר איזון משאבים במועד פקיעת הנישואין, ולא שיתוף בעלות שוטף במהלך הנישואין. עד אז כל צד הוא בעלים של נכסיו.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333005', '22222222-2222-2222-2222-222222222002', 'דירה שקיבלה האישה בירושה במהלך הנישואין ונשארה על שמה בלבד. מה הכלל?', '[{"id":"a","text":"נכנסת תמיד לאיזון מחצה על מחצה"},{"id":"b","text":"לא נכנסת לאיזון, אלא אם הוכח שהוסכם אחרת או שהתמזגה לרכוש המשותף"},{"id":"c","text":"שייכת תמיד לבעל כמפרנס"},{"id":"d","text":"שייכת לילדים בלבד"}]'::jsonb, 'b', 'סעיף 5 לחוק מוציא מכלל האיזון נכסים שהתקבלו במתנה או בירושה. אם הדירה נשמרה בנפרד, היא בדרך כלל נשארת מחוץ לאיזון. מיזוג או הסכמה אחרת יכולים לשנות את התוצאה.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333006', '22222222-2222-2222-2222-222222222002', 'האם חשבון שכר שנצבר מעבודה במהלך הנישואין נכנס לאיזון?', '[{"id":"a","text":"כן, ככלל זה משאב שנצבר בתקופת הנישואין"},{"id":"b","text":"לא, כי השכר תמיד אישי"},{"id":"c","text":"רק אם נפתח חשבון משותף"},{"id":"d","text":"רק אחרי עשר שנות נישואין"}]'::jsonb, 'a', 'משאבים שנצברו מעבודה בתקופת הנישואין הם הליבה של איזון המשאבים. עצם רישום החשבון על שם אחד הצדדים אינו מוציא אותו מהאיזון.', 3) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333007', '22222222-2222-2222-2222-222222222003', 'מה השינוי המרכזי שעולה מבע״מ 919/15?', '[{"id":"a","text":"רק האם חבה במזונות"},{"id":"b","text":"כאשר זמני השהות משמעותיים אצל שני ההורים, נטל המזונות נבחן לפי הכנסות וזמני שהות"},{"id":"c","text":"אין יותר מזונות ילדים בישראל"},{"id":"d","text":"מזונות נקבעים תמיד בסכום קבוע בחוק"}]'::jsonb, 'b', 'בית המשפט העליון קבע שיש להתאים את חלוקת הנטל למציאות של משמורת משמעותית אצל שני ההורים, לפי יחס ההכנסות וזמני השהות, ולא לפי חזקה אוטומטית על האב בלבד.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333008', '22222222-2222-2222-2222-222222222003', 'האם בע״מ 919/15 מבטל לחלוטין את הדין האישי במזונות ילדים יהודים?', '[{"id":"a","text":"כן, הדין האישי בוטל לגמרי בכל גיל"},{"id":"b","text":"לא. יש להבחין, במיוחד בצרכים הכרחיים בגיל הרך, וההלכה יושמה בהקשרים מסוימים"},{"id":"c","text":"כן, אבל רק לבני זוג מוסלמים"},{"id":"d","text":"ההלכה חלה רק על ילדים בגירים"}]'::jsonb, 'b', 'ההלכה שינתה את אופן חישוב הנטל במצבים של זמני שהות משמעותיים, אך לא מחקה את הדין האישי. בלימוד ובפרקטיקה יש לבדוק גיל, סוג הצרכים, והאם זמני השהות אכן משמעותיים.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333009', '22222222-2222-2222-2222-222222222003', 'מה נכון לגבי צרכי הילד בחישוב מזונות?', '[{"id":"a","text":"מתחילים מצרכי הילד, ואז בוחנים את יכולת ההורים וזמני השהות"},{"id":"b","text":"מתחילים תמיד מאחוז קבוע מהשכר ברוטו"},{"id":"c","text":"מתעלמים מצרכים אם ההכנסות שוות"},{"id":"d","text":"רק שכר דירה נחשב צורך"}]'::jsonb, 'a', 'נקודת המוצא היא צרכי הילד בפועל, ואחר כך חלוקת הנטל בין ההורים לפי יכולת כלכלית וזמני שהות. אין אחוז קבוע בחוק שמחליף בחינה זו.', 3) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333010', '22222222-2222-2222-2222-222222222004', 'מי הם האפוטרופסים הטבעיים של קטין?', '[{"id":"a","text":"רק ההורה שגר עם הילד"},{"id":"b","text":"שני ההורים"},{"id":"c","text":"רק סבתא מצד האם"},{"id":"d","text":"רק האפוטרופוס הכללי"}]'::jsonb, 'b', 'סעיף 14 לחוק הכשרות המשפטית והאפוטרופסות קובע ששני ההורים הם האפוטרופסים הטבעיים. החזקה או זמני שהות אינם שוללים אפוטרופסות, אלא אם הוגבלה בהחלטה שיפוטית.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333011', '22222222-2222-2222-2222-222222222004', 'מהו עקרון העל בהחלטה על החזקת קטין וזמני שהות?', '[{"id":"a","text":"רצון ההורה שהגיש ראשון את התביעה"},{"id":"b","text":"טובת הילד"},{"id":"c","text":"הכנסתו הגבוהה יותר של אחד ההורים"},{"id":"d","text":"מקום הרישום במרשם האוכלוסין בלבד"}]'::jsonb, 'b', 'טובת הילד היא אמת המידה המרכזית. בית המשפט בוחן קשר עם שני ההורים, יציבות, מסוגלות הורית וסיכונים, ולא את נוחות ההורה כשיקול מכריע.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333012', '22222222-2222-2222-2222-222222222004', 'האם הסכם בין הורים על זמני שהות מחייב את בית המשפט תמיד?', '[{"id":"a","text":"כן, הסכם הורים גובר תמיד על טובת הילד"},{"id":"b","text":"לא. בית המשפט יכול שלא לאשר הסכם אם אינו לטובת הילד"},{"id":"c","text":"כן, אם נחתם בפני עורך דין אחד"},{"id":"d","text":"רק אם הילד מעל גיל 16"}]'::jsonb, 'b', 'הסכמות הורים חשובות ומעודדות, אך בית המשפט מאשר אותן רק אם הן מתיישבות עם טובת הילד. קטין אינו צד חוזי רגיל.', 3) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333013', '22222222-2222-2222-2222-222222222005', 'איך מאשרים הסכם ממון שנכרת לפני הנישואין?', '[{"id":"a","text":"רק בבית המשפט העליון"},{"id":"b","text":"אפשר לאשר גם אצל נוטריון"},{"id":"c","text":"אין צורך באישור כלשהו"},{"id":"d","text":"רק ברשות המסים"}]'::jsonb, 'b', 'סעיף 2 לחוק יחסי ממון מאפשר לאשר הסכם ממון שנכרת לפני הנישואין גם בפני נוטריון. אחרי הנישואין נדרש בדרך כלל אישור שיפוטי.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333014', '22222222-2222-2222-2222-222222222006', 'ידועים בציבור שנפרדו. איזו ערכאה דנה בדרך כלל בחלוקת רכוש ביניהם?', '[{"id":"a","text":"בית הדין הרבני, כי מדובר במעמד אישי"},{"id":"b","text":"בית המשפט לענייני משפחה"},{"id":"c","text":"בית דין לעבודה"},{"id":"d","text":"אין ערכאה מוסמכת"}]'::jsonb, 'b', 'ידועים בציבור אינם נשואים, ולכן אין סמכות ייחודית לבית הדין הרבני בעניינם כזוג נשוי. הסכסוך הרכושי נדון בבית המשפט לענייני משפחה.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333015', '22222222-2222-2222-2222-222222222007', 'מהו הרעיון המרכזי של מרוץ הסמכויות?', '[{"id":"a","text":"שתי הערכאות תמיד דנות יחד באותו תיק"},{"id":"b","text":"הגשה ראשונה בערכאה מסוימת, עם כריכה כדין, עלולה לקבוע היכן יידונו עניינים כרוכים"},{"id":"c","text":"רק בית המשפט העליון קובע סמכות בכל תיק"},{"id":"d","text":"אין חשיבות למועד ההגשה"}]'::jsonb, 'b', 'מי שמקדים להגיש, ובמיוחד אם כורך כדין עניינים נלווים לתביעת גירושין בבית הדין, עלול לקבוע את הערכאה. לכן בודקים כנות כריכה ולא רק את עצם ההגשה.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333016', '22222222-2222-2222-2222-222222222007', 'האם די בהגשת תביעת גירושין בבית הדין כדי להעביר אוטומטית גם את עניין הילדים?', '[{"id":"a","text":"כן, כל תביעת גירושין כורכת הכול"},{"id":"b","text":"לא. נדרשת כריכה כנה ועל פי דין של העניין הספציפי"},{"id":"c","text":"כן, אבל רק אם יש הסכם ממון"},{"id":"d","text":"רק אם הילדים מעל גיל 18"}]'::jsonb, 'b', 'כריכה אינה אוטומטית. צריך לכרוך את העניין עצמו, בכנות ועל פי דין. ניסיון מלאכותי לשלול סמכות מבית המשפט לענייני משפחה עלול להיכשל.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333017', '22222222-2222-2222-2222-222222222008', 'מה מאפשר חוק בתי דין רבניים (קיום פסקי דין של גירושין)?', '[{"id":"a","text":"לבטל את הצורך בגט"},{"id":"b","text":"להטיל סנקציות על מי שמסרב לקיים פסק דין לגירושין"},{"id":"c","text":"לתת גט אזרחי במקום בית הדין"},{"id":"d","text":"רק לקנוס את עורך הדין"}]'::jsonb, 'b', 'החוק נועד לקיים פסק דין לגירושין באמצעות הגבלות וסנקציות. הוא אינו מחליף את הגט עצמו ואינו הופך את בית המשפט לענייני משפחה לנותן גט.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333018', '22222222-2222-2222-2222-222222222008', 'האם תביעת נזיקין בשל סרבנות גט מחליפה את הגט?', '[{"id":"a","text":"כן, פיצוי כספי מסיים את הנישואין"},{"id":"b","text":"לא. פיצוי עשוי להיות סעד נלווה, אבל המעמד האישי נותר עד לגט"},{"id":"c","text":"כן, אם נפסק יותר ממיליון ש״ח"},{"id":"d","text":"רק אם שני הצדדים מוסלמים"}]'::jsonb, 'b', 'נזיקין עשויים לפצות על נזק שנגרם מסרבנות, אך אינם מפקיעים את הנישואין. בלי גט, בני הזוג היהודים שנשאו כדת משה וישראל נותרים נשואים.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333019', '22222222-2222-2222-2222-222222222009', 'מה נכון להבחנה בין מזונות אישה למזונות ילדים?', '[{"id":"a","text":"זו אותה חובה, רק בשם אחר"},{"id":"b","text":"אלו חובות נפרדות, עם מקורות דין ותקופות שונות"},{"id":"c","text":"מזונות אישה תמיד נמשכים לכל החיים אחרי גט"},{"id":"d","text":"רק מזונות אישה קיימים בישראל"}]'::jsonb, 'b', 'מזונות ילדים נועדו לצורכי הקטין. מזונות אישה נשענים בעיקר על הדין האישי במהלך הנישואין. אחרי גט, ככלל אין מזונות אישה מתמשכים כמו במודל של מזונות בן זוג לכל החיים.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333020', '22222222-2222-2222-2222-222222222009', 'אישה יהודייה נשואה מבקשת מזונות אישה. מתי החובה קיימת בדרך כלל?', '[{"id":"a","text":"רק אחרי הגט"},{"id":"b","text":"כל עוד הנישואין קיימים, כל עוד לא הורתה עילה לשלילתם"},{"id":"c","text":"רק אם יש ילדים"},{"id":"d","text":"רק אם נחתם הסכם ממון"}]'::jsonb, 'b', 'חובת מזונות האישה בדין האישי היהודי קשורה לקיום הנישואין. יש עילות לשלילת מזונות, אבל נקודת המוצא אינה "רק אחרי גט" ואינה תלויה בהולדת ילדים.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333021', '22222222-2222-2222-2222-222222222010', 'מהו מקור הסמכות העיקרי לצו הגנה בין בני משפחה?', '[{"id":"a","text":"חוק החוזים"},{"id":"b","text":"חוק למניעת אלימות במשפחה, התשנ״א-1991"},{"id":"c","text":"רק פקודת הנזיקין"},{"id":"d","text":"רק דיני הגט"}]'::jsonb, 'b', 'צו הגנה בין בני משפחה נשען בראש ובראשונה על החוק למניעת אלימות במשפחה. אפשר לבקשו גם במעמד צד אחד כשיש דחיפות.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333022', '22222222-2222-2222-2222-222222222010', 'האם צו הגנה מחליט גם על חלוקת הדירה באיזון משאבים?', '[{"id":"a","text":"כן, הצו מסיים את כל ענייני הרכוש"},{"id":"b","text":"לא. זה סעד חירום להגנה; רכוש ומשמורת נדונים במסלולים מתאימים"},{"id":"c","text":"כן, אם הצו ניתן לשנה"},{"id":"d","text":"רק אם נרשם בטאבו"}]'::jsonb, 'b', 'צו הגנה יכול להרחיק אדם מהבית כדי למנוע אלימות. הוא אינו פסק דין לחלוקת רכוש ואינו תחליף להליך על משמורת או איזון משאבים.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333023', '22222222-2222-2222-2222-222222222011', 'אין צוואה. יש בן זוג וילדים. מה מקבל בן הזוג מן היתרה אחרי מיטלטלין ומכונית?', '[{"id":"a","text":"את כל העיזבון"},{"id":"b","text":"מחצית היתרה, והילדים את המחצית השנייה"},{"id":"c","text":"רק שקל אחד סמלי"},{"id":"d","text":"כלום, כי הכול לילדים"}]'::jsonb, 'b', 'סעיף 11 לחוק הירושה: בן הזוג מקבל את מיטלטלי משק הבית ואת המכונית, ומחצית מהיתרה כשיש ילדים. הילדים חולקים את המחצית האחרת.', 1) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, lesson_id, prompt, options, correct_option_id, explanation, sort_order) values ('33333333-3333-3333-3333-333333333024', '22222222-2222-2222-2222-222222222011', 'האם דירה שירש אדם במהלך הנישואין נכנסת אוטומטית לאיזון משאבים?', '[{"id":"a","text":"כן, כל ירושה מתחלקת מיד עם בן הזוג"},{"id":"b","text":"לא ככלל. ירושה מוצאת מאיזון אלא אם הוסכם אחרת או שהנכס התמזג"},{"id":"c","text":"כן, לפי חוק הירושה בלבד"},{"id":"d","text":"רק אם היורש הוא האישה"}]'::jsonb, 'b', 'חוק הירושה קובע מי יורש את המוריש. חוק יחסי ממון מוציא ירושה מכלל האיזון, כל עוד לא הוכח שיתוף או הסכמה אחרת. אלו שתי מערכות נפרדות.', 2) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, options = excluded.options, correct_option_id = excluded.correct_option_id, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444001', '22222222-2222-2222-2222-222222222001', 'דנה ויוסי: גירושין, דירה וילדים', 'דנה ויוסי נשואים כדת משה וישראל, ולהם שני ילדים. יוסי הגיש לבית הדין הרבני תביעת גירושין וכרך אליה את עניין הדירה המשותפת ואת החזקת הילדים. דנה טוענת שהכריכה אינה כנה: יוסי ממשיך לגור בבית ואינו באמת מבקש להתגרש כעת, אלא רק למנוע דיון בבית המשפט לענייני משפחה.', 'אילו שאלות תשאלי קודם, ולאיזו ערכאה סביר שהעניינים יידונו?', 'עצם הגירושין יידון בבית הדין הרבני. לגבי הדירה והילדים יש לבדוק אם הכריכה כנה ועל פי דין. אם בית הדין ישתכנע שהכריכה מלאכותית, הוא עלול לדחות את הסמכות בעניינים הכרוכים, ואז יידונו בבית המשפט לענייני משפחה. זה תרחיש שכיח בסכסוכי סמכות, ולא תרגיל תאורטי.', 'חוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי״ג-1953, סעיף 3; חוק בתי המשפט לענייני משפחה, התשנ״ה-1995.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444002', '22222222-2222-2222-2222-222222222002', 'דירת הירושה וחשבון החיסכון', 'מיכל ירשה מאביה דירה בתל אביב במהלך הנישואין. הדירה נשארה על שמה, הושכרה, ודמי השכירות הופקדו לחשבון משותף שממנו מומנו חופשות וחיי היום-יום. במקביל נצברו בקרן ההשתלמות של בן זוגה כ-180,000 ש״ח מעבודה במהלך הנישואין. אין הסכם ממון.', 'מה נכנס לאיזון, ומה דורש זהירות מיוחדת?', 'קרן ההשתלמות שנצברה מעבודה בתקופת הנישואין נכנסת ככלל לאיזון. הדירה עצמה היא ירושה ולכן חזקה שאינה מתאזנת. עם זאת, הפקדת דמי השכירות לחשבון משותף והשימוש בהם לצורכי המשפחה עלולים להשפיע על טענת מיזוג או על איזון פירות. זה מקרה טיפוסי שבו מפרידים בין הקרן (הדירה) לבין הפירות וההתנהגות הכלכלית בפועל.', 'חוק יחסי ממון בין בני זוג, התשל״ג-1973, סעיפים 4 ו-5.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444003', '22222222-2222-2222-2222-222222222003', 'זמני שהות כמעט שווים ושכר שונה', 'לאור ולנועה שני ילדים בני 8 ו-11. זמני השהות הם כמעט שווים. אור משתכר 28,000 ש״ח נטו, לנועה 12,000 ש״ח נטו. לנועה הוצאות מדור גבוהות יותר. אור טוען שאחרי בע״מ 919/15 הוא אינו חייב במזונות כלל.', 'האם טענתו של אור מדויקת? איך ניגשים לחישוב?', 'הטענה אינה מדויקת. בע״מ 919/15 אינו פוטר הורה ממזונות רק כי יש זמני שהות שווים. בודקים את צרכי הילדים, את יחס ההכנסות, את מה שכל הורה כבר מוציא בזמן השהות אצלו, ואת המדור. ייתכן שאור עדיין יישא בחלק גדול יותר בגלל פערי השכר, גם אם לא במלוא הסכום שהיה נפסק במודל הישן.', 'בע״מ 919/15 פלוני נ׳ פלונית (נבו, 19.7.2017).', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444004', '22222222-2222-2222-2222-222222222004', 'מעבר עיר והתנגדות האב', 'האם מבקשת לעבור עם הילדים מחיפה לבאר שבע לטובת עבודה. האב מתנגד כי המעבר יצמצם את זמני השהות באמצע השבוע. הילדים משולבים בבית ספר ובחוגים, ואין ממצא של מסוכנות אצל אף הורה.', 'מה ישקול בית המשפט, ומה לא יוכרע לפי נוחות ההורה בלבד?', 'בית המשפט ישקול את טובת הילדים: יציבות חינוכית, איכות הקשר עם שני ההורים, יכולת לקיים זמני שהות אחרי המעבר, וסיבת המעבר. אין זכות אוטומטית להורה המשמורן לעבור עיר. גם אין וטו אוטומטי להורה השני. התוצאה תלויה בעובדות, ולעיתים בפתרון ביניים כמו דחיית מעבר עד סוף שנת הלימודים.', 'חוק הכשרות המשפטית והאפוטרופסות, התשכ״ב-1962, סעיפים 24 ו-25.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444005', '22222222-2222-2222-2222-222222222005', 'הסכם ממון בכתב יד לפני החתונה', 'בני הזוג חתמו בכתב יד, שבוע לפני החתונה, שכל אחד יישאר עם הנכסים שעל שמו. ההסכם לא אושר אצל נוטריון ולא בבית משפט. כעבור שתים-עשרה שנה מתבקש איזון משאבים.', 'האם ההסכם מספיק כדי למנוע איזון?', 'הסכם ממון טעון אישור כדין. הסכם בכתב יד שלא אושר בדרך הקבועה בחוק לא יחליף, ככלל, את הסדר איזון המשאבים. ייתכנו טענות אחרות (מניעות, הסכמות מאוחרות), אבל נקודת המוצא היא שההסכם אינו תקף כהסכם ממון.', 'חוק יחסי ממון בין בני זוג, התשל״ג-1973, סעיפים 1 ו-2.', 'review'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444006', '22222222-2222-2222-2222-222222222006', 'דירה שנרכשה במהלך חיים משותפים', 'רונית ואלון חיו יחד שמונה שנים ללא נישואין. הדירה נרשמה על שם אלון בלבד, אך רונית שילמה מחצית מהמשכנתא מחשבונה. אין הסכם חיים משותפים.', 'איזו ערכאה, ומהי טענה אפשרית של רונית?', 'הערכאה היא בית המשפט לענייני משפחה. רונית עשויה לטעון לשיתוף ספציפי בדירה על יסוד כוונת שיתוף והשקעה בפועל, אף שהזוג אינו נשוי. זה אינו אוטומטי: נטל ההוכחה עליה, והרישום על שם אלון הוא נקודת מוצא ולא סוף הדיון.', 'חוק בתי המשפט לענייני משפחה, התשנ״ה-1995; פסיקת השיתוף הספציפי בידועים בציבור.', 'draft'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444007', '22222222-2222-2222-2222-222222222007', 'הגשה ביום שישי בצהריים', 'עמית הגיש ביום חמישי תביעה לבית המשפט לענייני משפחה בעניין הילדים והדירה. ביום שישי בצהריים הגישה נועה תביעת גירושין בבית הדין הרבני וכרכה את אותם עניינים. עמית טוען שהכריכה נעשתה רק כדי לנצח במרוץ.', 'מה בודקים קודם, ומדוע מועד ההגשה אינו סוף הדיון?', 'בודקים איזו תביעה נפתחה קודם, ומה נכרך כדין ובכנות לתביעת הגירושין. עצם ההגשה בבית הדין אינה מכריעה אם הכריכה מלאכותית. אם בית הדין ימצא שהכריכה אינה כנה, העניינים הכרוכים עשויים להישאר בבית המשפט לענייני משפחה. המרוץ מסביר את הלחץ להגיש, לא את התוצאה המשפטית לבדה.', 'חוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי״ג-1953, סעיף 3; חוק בתי המשפט לענייני משפחה, התשנ״ה-1995.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444008', '22222222-2222-2222-2222-222222222008', 'פסק דין לגט בלי גט', 'בית הדין חייב את דן במתן גט. דן לא התייצב לסידור הגט כבר שנה, ממשיך להחזיק דרכון, ואומר שרק פיצוי כספי "יישב את העניין". שירה שוקלת בקשה לסנקציות וגם תביעת נזיקין.', 'אילו כלים קיימים, ומה אף אחד מהם לא עושה לבדו?', 'אפשר לבקש סנקציות לפי חוק קיום פסקי דין של גירושין: הגבלות על דרכון, רישיון וחשבונות, ובמקרים מתאימים מאסר. תביעת נזיקין עשויה לפצות, אך לא תסיים את הנישואין. בלי גט שירה נותרת נשואה. הכלים נועדו לשבור סרבנות, לא להחליף את הגט.', 'חוק בתי דין רבניים (קיום פסקי דין של גירושין), התשנ״ה-1995.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444009', '22222222-2222-2222-2222-222222222009', 'בקשת מזונות אחרי הפירוד ולפני הגט', 'יעל וגיא יהודים נשואים, נפרדו לפני חצי שנה, וטרם ניתן גט. ליעל אין הכנסה מספקת. גיא משלם מזונות לילדים וטוען שאינו חייב דבר ליעל כי הם כבר לא גרים יחד.', 'האם הפירוד בפועל מבטל מזונות אישה?', 'פירוד מגורים אינו גט. כל עוד הנישואין קיימים, עשויה לעמוד ליעל עילת מזונות אישה לפי הדין האישי, בכפוף לסייגים (למשל התנהגות ששוללת מזונות). מזונות הילדים שגיא משלם אינם תחליף אוטומטי למזונות האישה. אחרי גט התמונה משתנה, ואין להניח מזונות אישה מתמשכים כברירת מחדל.', 'חוק לתיקון דיני המשפחה (מזונות), התשי״ט-1959; הדין האישי לעניין מזונות אישה.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444010', '22222222-2222-2222-2222-222222222010', 'בקשת צו הגנה בלילה', 'אחרי ויכוח אלים בבית, מיכל מבקשת בבוקר צו הגנה נגד בן זוגה. יש חבורות, והילדים בבית. בן הזוג מחזיק רישיון לנשק. היא חוששת להמתין לדיון במעמד שני הצדדים.', 'איזה סעד דחוף אפשרי, ומה הצו לא יכריע?', 'אפשר לבקש צו הגנה גם במעמד צד אחד כשיש דחיפות. הצו עשוי להרחיק מהבית, לאסור יצירת קשר, ולהורות על הפקדת נשק. משך הצו מוגבל ויש דיון המשך. הוא לא יחלק את הדירה ולא יקבע משמורת קבועה; אלה הליכים נפרדים, גם אם העובדות חופפות.', 'חוק למניעת אלימות במשפחה, התשנ״א-1991.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
insert into public.cases (id, lesson_id, title, facts, question, discussion, sources, status) values ('44444444-4444-4444-4444-444444444011', '22222222-2222-2222-2222-222222222011', 'עיזבון בלי צוואה ודירת ירושה', 'אביו של רועי נפטר בלי צוואה. היורשים הם רועי, אחותו, ואלמנתו של האב (אמם החורגת). בנוסף, רועי עצמו נשוי וירש מהאב דירה שנשארה על שמו. אשתו טוענת שהדירה נכנסת לאיזון כי נרכשה "בתקופת הנישואין".', 'מי יורש את האב, ומה דין הדירה בין רועי לאשתו?', 'עיזבון האב מתחלק לפי חוק הירושה: האלמנה מקבלת מיטלטלין ומכונית ומחצית היתרה, ורועי ואחותו חולקים את המחצית האחרת. הדירה שירש רועי נבחנת מול אשתו לפי חוק יחסי ממון: ירושה ככלל מחוץ לאיזון, אלא אם הוכח מיזוג או הסכמה. אין לערבב בין חלוקת עיזבון האב לבין איזון המשאבים של רועי.', 'חוק הירושה, התשכ״ה-1965, סעיף 11; חוק יחסי ממון בין בני זוג, התשל״ג-1973, סעיף 5.', 'published'::public.content_status) on conflict (id) do update set lesson_id = excluded.lesson_id, title = excluded.title, facts = excluded.facts, question = excluded.question, discussion = excluded.discussion, sources = excluded.sources, status = excluded.status;
